      ],
      "materiality_rationale": "The agreement identifies the threshold governing the stop instruction; removing it would leave the trigger unspecified.",
      "resolution_rationale": "The supplied agreement is invoked at its original workload-allocation scope and strength. The generated response to exceeding it remains the primary governance assertion."
    },
    {
      "dependency_id": "R3K08-C1-D2",
      "subject": "Workload is measured reliably.",
      "dependency_classification": {
        "content_origin": "TARGET_SUPPLIED",
        "epistemic_function": "FACT",
        "assertion_mode": "REFERENCED_PREMISE",
        "origin_refs": [
