          "role": "CONTEXT"
        }
      ],
      "materiality_rationale": "Reliable workload measurement is material to applying the threshold-triggered instruction under the supplied stopping-rule guidance.",
      "resolution_rationale": "The case condition is invoked at the target's stated scope and certainty, without asserting additional measurement capabilities or operations."
    },
    {
      "dependency_id": "R3K08-C1-D3",
      "subject": "Stopping is safe.",
      "dependency_classification": {
        "content_origin": "TARGET_SUPPLIED",
