      "claim_ref": null,
      "provenance_refs": [
        {
          "source_id": "R3K08-T",
          "role": "SUPPORT"
        }
      ],
      "materiality_rationale": "If stopping were unsafe, the prescribed response could not retain essentially the same acceptance under the frozen case conditions.",
      "resolution_rationale": "Safety is invoked only for stopping in this case, preserving the supplied scope and strength. Ordinary stopping introduces no separate substantive operation."
    },
    {
      "dependency_id": "R3K08-C1-D4",
      "subject": "Prospective stopping rules can use a reliably observed workload and an explicitly agreed policy threshold.",
      "dependency_classification": {
